# PLAN: "Stun-lock" composition built around crowd control.
# Draft: Heart of Ruin (stunning dash engager), Marcella, Cassi/Issac, Prism,
#        Varg, then Stellar and Willow as fill. None of these are our usual picks.
# Roles:
#  - Every champion looks at its own slots and casts any stunning slot first
#    (slot_stun > 0) before anything else. A dash that stuns is used to gap-close.
#    Damage and area slots come next, then the basic attack, then an attack reset.
#  - Heart of Ruin and Varg buy health; Prism and Cassi/Issac buy focus; the rest buy strength.
#  - Fight only when local_strength favours us or the target is nearly dead.
#    When we must retreat, a stun covers the escape.
#  - Otherwise farm gem camps (skipping golem and monolith groups), claiming them
#    so allies spread out. Capture cleared groups, and tribute at 40 gems
#    (or any gems late in the game).

def use_slot(s, u, t):
  if ability_ready(s):
    if slot_stun(s) > 0:
      if slot_is_dash(s):
        if distance(position(), t) <= slot_range(s) + 1:
          dash_towards(s, t)
      elif distance(position(), t) <= slot_range(s):
        if slot_radius(s) > 0:
          cast_at_tile(s, t)
        else:
          cast_at_unit(s, u)
    elif slot_is_damage(s):
      if distance(position(), t) <= slot_range(s):
        cast_at_unit(s, u)
    elif slot_is_aoe(s):
      if distance(position(), t) <= slot_range(s):
        cast_at_tile(s, t)
    elif slot_is_shield(s):
      cast_self(s)
    elif slot_is_heal(s):
      if health() < 0.8 * max_health():
        cast_self(s)

def stun_only(s, u, t):
  if ability_ready(s):
    if slot_stun(s) > 0:
      if not slot_is_dash(s):
        if distance(position(), t) <= slot_range(s):
          if slot_radius(s) > 0:
            cast_at_tile(s, t)
          else:
            cast_at_unit(s, u)
    elif slot_is_shield(s):
      cast_self(s)

def shop():
  if gold() >= 30:
    if i_am(champ_heart_of_ruin()) or i_am(champ_varg()):
      buy(shard(stat_health()), floor(gold() / 30))
    elif i_am(champ_prism()) or i_am(champ_cassi_issac()):
      buy(shard(stat_focus()), floor(gold() / 30))
    else:
      buy(shard(stat_strength()), floor(gold() / 30))

