let alt = closest(minus(altars(), locked_altars()))
if gems() >= 40 or (gems() > 0 and round_number() > 1850):
  if exists(alt):
    if distance(pos, alt) <= 1:
      tribute(alt)
    else:
      move_towards(alt)
    end_turn()

